#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    int factor = 3;
    std::vector<int> v = {1,2,3};
    std::vector<int> a(v.size());
    std::transform(v.begin(), v.end(), a.begin(), [factor](int x){ return x * factor; });
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';
    int total = 0;
    std::for_each(v.begin(), v.end(), [&total](int x){ total += x; });
    std::cout << "sum(ref capture) = " << total << '\n';
    int n = 0;
    auto f = [n]() mutable { return ++n; };
    std::cout << f() << ' ' << f() << ' ' << f() << '\n';
    std::cout << "外部 n 仍为 " << n << '\n';
}
